// ---------------------------------------------------------------------------
// Runtime loader
// ---------------------------------------------------------------------------

type CreateInstanceFn = unsafe extern "system" fn(*mut NV_ENCODE_API_FUNCTION_LIST) -> NVENCSTATUS;
type GetMaxVersionFn = unsafe extern "system" fn(*mut u32) -> NVENCSTATUS;

/// Loaded NVENC entry points. Lives for the whole process.
pub struct Api {
    pub fns: NV_ENCODE_API_FUNCTION_LIST,
    pub driver_max_version: u32,
    _lib: libloading::Library,
}

// SAFETY: the function table is immutable after creation and NVENC entry points
// are thread-safe at the API level (sessions themselves are not shared).
unsafe impl Send for Api {}
unsafe impl Sync for Api {}

#[derive(Debug)]
pub enum LoadError {
    Dll(libloading::Error),
    DriverTooOld { driver: u32, required: u32 },
    Status(&'static str, NVENCSTATUS),
}

impl std::fmt::Display for LoadError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            LoadError::Dll(e) => write!(f, "failed to load nvEncodeAPI64.dll: {e}"),
            LoadError::DriverTooOld { driver, required } => write!(
                f,
                "NVIDIA driver supports NVENC API {}.{}, need {}.{}",
                driver >> 4,
                driver & 0xf,
                required >> 4,
                required & 0xf
            ),
            LoadError::Status(call, s) => write!(f, "{call} failed: {}", status_name(*s)),
        }
    }
}

impl std::error::Error for LoadError {}

static API: OnceLock<Result<Api, String>> = OnceLock::new();

/// Load NVENC once per process.
pub fn api() -> Result<&'static Api, String> {
    API.get_or_init(|| unsafe { load() }.map_err(|e| e.to_string()))
        .as_ref()
        .map_err(Clone::clone)
}

unsafe fn load() -> Result<Api, LoadError> {
    let lib = libloading::Library::new("nvEncodeAPI64.dll").map_err(LoadError::Dll)?;
    let get_max: libloading::Symbol<GetMaxVersionFn> = lib
        .get(b"NvEncodeAPIGetMaxSupportedVersion\0")
        .map_err(LoadError::Dll)?;
    let create: libloading::Symbol<CreateInstanceFn> = lib
        .get(b"NvEncodeAPICreateInstance\0")
        .map_err(LoadError::Dll)?;

    let mut driver = 0u32;
    let s = get_max(&mut driver);
    if s != _NVENCSTATUS_NV_ENC_SUCCESS {
        return Err(LoadError::Status("NvEncodeAPIGetMaxSupportedVersion", s));
    }
    let required = (NVENCAPI_MAJOR_VERSION << 4) | NVENCAPI_MINOR_VERSION;
    if driver < required {
        return Err(LoadError::DriverTooOld { driver, required });
    }

    let mut fns: NV_ENCODE_API_FUNCTION_LIST = std::mem::zeroed();
    fns.version = NV_ENCODE_API_FUNCTION_LIST_VER;
    let s = create(&mut fns);
    if s != _NVENCSTATUS_NV_ENC_SUCCESS {
        return Err(LoadError::Status("NvEncodeAPICreateInstance", s));
    }
    drop(get_max);
    drop(create);
    Ok(Api {
        fns,
        driver_max_version: driver,
        _lib: lib,
    })
}

pub fn status_name(s: NVENCSTATUS) -> &'static str {
    match s {
        _NVENCSTATUS_NV_ENC_SUCCESS => "NV_ENC_SUCCESS",
        _NVENCSTATUS_NV_ENC_ERR_NO_ENCODE_DEVICE => "NO_ENCODE_DEVICE",
        _NVENCSTATUS_NV_ENC_ERR_UNSUPPORTED_DEVICE => "UNSUPPORTED_DEVICE",
        _NVENCSTATUS_NV_ENC_ERR_INVALID_ENCODERDEVICE => "INVALID_ENCODERDEVICE",
        _NVENCSTATUS_NV_ENC_ERR_INVALID_DEVICE => "INVALID_DEVICE",
        _NVENCSTATUS_NV_ENC_ERR_DEVICE_NOT_EXIST => "DEVICE_NOT_EXIST",
        _NVENCSTATUS_NV_ENC_ERR_INVALID_PTR => "INVALID_PTR",
        _NVENCSTATUS_NV_ENC_ERR_INVALID_EVENT => "INVALID_EVENT",
        _NVENCSTATUS_NV_ENC_ERR_INVALID_PARAM => "INVALID_PARAM",
        _NVENCSTATUS_NV_ENC_ERR_INVALID_CALL => "INVALID_CALL",
        _NVENCSTATUS_NV_ENC_ERR_OUT_OF_MEMORY => "OUT_OF_MEMORY",
        _NVENCSTATUS_NV_ENC_ERR_ENCODER_NOT_INITIALIZED => "ENCODER_NOT_INITIALIZED",
        _NVENCSTATUS_NV_ENC_ERR_UNSUPPORTED_PARAM => "UNSUPPORTED_PARAM",
        _NVENCSTATUS_NV_ENC_ERR_LOCK_BUSY => "LOCK_BUSY",
        _NVENCSTATUS_NV_ENC_ERR_NOT_ENOUGH_BUFFER => "NOT_ENOUGH_BUFFER",
        _NVENCSTATUS_NV_ENC_ERR_INVALID_VERSION => "INVALID_VERSION",
        _NVENCSTATUS_NV_ENC_ERR_MAP_FAILED => "MAP_FAILED",
        _NVENCSTATUS_NV_ENC_ERR_NEED_MORE_INPUT => "NEED_MORE_INPUT",
        _NVENCSTATUS_NV_ENC_ERR_ENCODER_BUSY => "ENCODER_BUSY",
        _NVENCSTATUS_NV_ENC_ERR_EVENT_NOT_REGISTERD => "EVENT_NOT_REGISTERD",
        _NVENCSTATUS_NV_ENC_ERR_GENERIC => "GENERIC",
        _NVENCSTATUS_NV_ENC_ERR_INCOMPATIBLE_CLIENT_KEY => "INCOMPATIBLE_CLIENT_KEY",
        _NVENCSTATUS_NV_ENC_ERR_UNIMPLEMENTED => "UNIMPLEMENTED",
        _NVENCSTATUS_NV_ENC_ERR_RESOURCE_REGISTER_FAILED => "RESOURCE_REGISTER_FAILED",
        _NVENCSTATUS_NV_ENC_ERR_RESOURCE_NOT_REGISTERED => "RESOURCE_NOT_REGISTERED",
        _NVENCSTATUS_NV_ENC_ERR_RESOURCE_NOT_MAPPED => "RESOURCE_NOT_MAPPED",
        _ => "UNKNOWN",
    }
}
